user = frappe.session.user

roles = [r[0] for r in frappe.db.sql("""
    SELECT role FROM `tabHas Role` WHERE parent = %s
""", (user,))]

if user == 'Administrator' or 'Sabre Head Of Sales' in roles or 'System Manager' in roles:
    conditions = ''
elif 'Sabre Product Team' in roles:
    conditions = '`tabSabre Business Case`.product_owner = ' + frappe.db.escape(user)
else:
    conditions = '`tabSabre Business Case`.pipeline_am = ' + frappe.db.escape(user)

# Server Script: Sync Sabre Agency with HD Customer and Contact
# Event: After Save

agency_title = doc.get("agency_name") or doc.name
agency_email = doc.get("email")
agency_phone = doc.get("phone")

target_hd_customer = None

# Step 1: Sync or Create HD Customer
if doc.get("customer") and frappe.db.exists("HD Customer", doc.customer):
    target_hd_customer = doc.customer
    hd_cust_doc = frappe.get_doc("HD Customer", doc.customer)
    
    if hd_cust_doc.get("customer_name") != agency_title:
        hd_cust_doc.customer_name = agency_title
        hd_cust_doc.flags.ignore_permissions = True
        hd_cust_doc.save()

else:
    if frappe.db.exists("HD Customer", agency_title):
        target_hd_customer = agency_title
    else:
        hd_payload = {
            "doctype": "HD Customer",
            "customer_name": agency_title
        }
        
        meta = frappe.get_meta("HD Customer")
        if meta.has_field("email") and agency_email:
            hd_payload["email"] = agency_email
            
        new_hd_customer = frappe.get_doc(hd_payload)
        new_hd_customer.flags.ignore_permissions = True
        new_hd_customer.insert()
        target_hd_customer = new_hd_customer.name

    doc.db_set("customer", target_hd_customer)


# Step 2: Create Contact for 3CX and Helpdesk
if agency_email or agency_phone:
    existing_contact = None
    if agency_email:
        existing_contact = frappe.db.get_value("Contact", {"email_id": agency_email})

    if not existing_contact:
        contact_doc = frappe.get_doc({
            "doctype": "Contact",
            "first_name": agency_title,
            "email_id": agency_email,
            "phone": agency_phone,
            "mobile_no": agency_phone,
            "links": [
                {"link_doctype": "HD Customer", "link_name": target_hd_customer},
                {"link_doctype": "Sabre Agency", "link_name": doc.name}
            ]
        })
        contact_doc.flags.ignore_permissions = True
        contact_doc.insert()

if not doc.get('csm_assigned'):
    team_members = frappe.db.sql("SELECT user FROM `tabHD Team Member` WHERE parent = %s", ('Sabre CSM Team',))
    members = [r[0] for r in team_members if r[0] and frappe.db.exists('User', r[0])]
    if members:
        counts = {}
        for m in members:
            counts[m] = frappe.db.count('Sabre Implementation', {'csm_assigned': m})
        chosen = min(counts, key=counts.get)
        doc.csm_assigned = chosen

if doc.workflow_state == 'Implementation' and doc.has_value_changed('workflow_state') and doc.customer:
    current_status = frappe.db.get_value('Sabre Agency', doc.customer, 'portfolio_status')
    if current_status == 'Prospect':
        frappe.db.set_value('Sabre Agency', doc.customer, 'portfolio_status', 'Existing Customer', update_modified=False)

if doc.customer and doc.pipeline_am:
    agency = frappe.db.get_value('Sabre Agency', doc.customer, ['account_manager', 'portfolio_status'], as_dict=True)
    if agency:
        updates = {}
        if not agency.account_manager:
            updates['account_manager'] = doc.pipeline_am
        if not agency.portfolio_status:
            updates['portfolio_status'] = 'Prospect'
        if updates:
            frappe.db.set_value('Sabre Agency', doc.customer, updates, update_modified=False)
